 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]
    # The pair sharing a row forms the crossbar; connect every other marker
    # vertically to that row.
    counts = {}
    for r, c in points:
        counts[r] = counts.get(r, 0) + 1
    bar_row = max(counts, key=lambda r: (counts[r], -r))
    bar_cols = [c for r, c in points if r == bar_row]
    for c in range(min(bar_cols), max(bar_cols) + 1):
        if out[bar_row][c] == 0:
            out[bar_row][c] = 3
    for r, c in points:
        if r < bar_row:
            for rr in range(r + 1, bar_row):
                if out[rr][c] == 0:
                    out[rr][c] = 3
        elif r > bar_row:
            for rr in range(bar_row + 1, r):
                if out[rr][c] == 0:
                    out[rr][c] = 3
    return out
